namespace XPScript.Compiler;

internal static class NotesDatabaseLifecyclePostProcessor
{
    public static string Apply(string source)
    {
        ArgumentNullException.ThrowIfNull(source);

        source = ReplaceRequired(
            source,
            "    public string Server { get; }\n    public string FilePath { get; }",
            "    public string Server { get; private set; }\n    public string FilePath { get; private set; }",
            "database-create-mutable-location");

        source = ReplaceRequired(
            source,
            "    public void RemoveFTIndex()\n    {\n        EnsureAlive();\n        if (!IsOpen) throw new XPScriptRuntimeException(91, \"NotesDatabase is not open.\");\n        Session.Api.DeleteFullTextIndex(_handle);\n    }",
            "    public void RemoveFTIndex()\n    {\n        EnsureAlive();\n        if (!IsOpen) throw new XPScriptRuntimeException(91, \"NotesDatabase is not open.\");\n        Session.Api.DeleteFullTextIndex(_handle);\n    }\n\n    public void Create(object? serverValue, object? fileValue, object? openFlagValue)\n        => Create(serverValue, fileValue, openFlagValue, 0);\n\n    public void Create(object? serverValue, object? fileValue, object? openFlagValue, object? maxSizeValue)\n    {\n        EnsureAlive();\n        var server = XPScriptRuntime.CStr(serverValue).Trim();\n        var file = XPScriptRuntime.CStr(fileValue).Trim();\n        if (server.Length == 0) server = Server;\n        if (file.Length == 0) file = FilePath;\n        if (file.Length == 0) throw new XPScriptRuntimeException(5, \"NotesDatabase.Create requires a database file path.\");\n        ValidateLegacyMaxSize(maxSizeValue);\n        CloseForDatabaseOperation();\n        Session.Api.CreateDatabase(server, file);\n        Server = server;\n        FilePath = file;\n        if (XPScriptRuntime.CBool(openFlagValue)) _handle = Session.Api.OpenDatabase(server, file);\n    }\n\n    public XPScriptNotesDatabase CreateCopy(object? serverValue, object? fileValue)\n        => CreateCopy(serverValue, fileValue, 0, false);\n\n    public XPScriptNotesDatabase CreateCopy(object? serverValue, object? fileValue, object? maxSizeValue)\n        => CreateCopy(serverValue, fileValue, maxSizeValue, false);\n\n    // XPscript extension: includeDocuments=True copies data notes as well as design notes.\n    public XPScriptNotesDatabase CreateCopy(object? serverValue, object? fileValue, object? maxSizeValue, object? includeDocumentsValue)\n    {\n        EnsureAlive();\n        if (!IsOpen) throw new XPScriptRuntimeException(91, \"NotesDatabase is not open.\");\n        var server = XPScriptRuntime.CStr(serverValue).Trim();\n        var file = XPScriptRuntime.CStr(fileValue).Trim();\n        if (file.Length == 0) throw new XPScriptRuntimeException(5, \"NotesDatabase.CreateCopy requires a destination database file path.\");\n        ValidateLegacyMaxSize(maxSizeValue);\n        var includeDocuments = XPScriptRuntime.CBool(includeDocumentsValue);\n        var handle = Session.Api.CreateDatabaseCopy(Server, FilePath, server, file, includeDocuments);\n        return new XPScriptNotesDatabase(Session, handle, server, file);\n    }\n\n    public void Remove()\n    {\n        EnsureAlive();\n        var server = Server;\n        var file = FilePath;\n        if (file.Length == 0) throw new XPScriptRuntimeException(5, \"NotesDatabase.Remove requires a database file path.\");\n        CloseForDatabaseOperation();\n        Session.Api.DeleteDatabase(server, file);\n    }\n\n    private static void ValidateLegacyMaxSize(object? maxSizeValue)\n    {\n        var maxSize = maxSizeValue is null ? 0 : XPScriptRuntime.CInt(maxSizeValue);\n        if (maxSize < 0 || maxSize > 4)\n            throw new XPScriptRuntimeException(5, \"NotesDatabase maxsize must be between 0 and 4 gigabytes.\");\n    }\n\n    private void CloseForDatabaseOperation()\n    {\n        while (true)\n        {\n            XPScriptNotesOwnedObject? child;\n            lock (_childrenGate) child = _children.Count == 0 ? null : _children[^1];\n            if (child is null) break;\n            try { child.Recycle(); }\n            catch { UnregisterChild(child); }\n        }\n        var handle = Interlocked.Exchange(ref _handle, 0);\n        if (handle != 0) Session.Api.CloseDatabase(handle);\n    }",
            "database-create-copy-remove-surface");

        source = ReplaceRequired(
            source,
            "    internal XPScriptNotesTimeDate GetDatabaseCreated(nint db)",
            "    internal void CreateDatabase(string server, string file)\n    {\n        EnsureInitialized();\n        using var fileText = ToLmbcs(file);\n        using var serverText = ToLmbcs(server);\n        nint networkPath = 0;\n        try\n        {\n            var path = fileText.Pointer;\n            if (server.Length > 0)\n            {\n                networkPath = System.Runtime.InteropServices.Marshal.AllocHGlobal(4096);\n                Zero(networkPath, 4096);\n                Check(Resolve<OSPathNetConstructDelegate>(\"OSPathNetConstruct\")(0, serverText.Pointer, fileText.Pointer, networkPath), \"OSPathNetConstruct\");\n                path = networkPath;\n            }\n            Check(Resolve<NSFDbCreateDelegate>(\"NSFDbCreate\")(path, unchecked((ushort)0xFF01), 0), \"NSFDbCreate\");\n        }\n        finally { if (networkPath != 0) System.Runtime.InteropServices.Marshal.FreeHGlobal(networkPath); }\n    }\n\n    internal nint CreateDatabaseCopy(string sourceServer, string sourceFile, string destinationServer, string destinationFile, bool includeDocuments)\n    {\n        EnsureInitialized();\n        using var sourceFileText = ToLmbcs(sourceFile);\n        using var sourceServerText = ToLmbcs(sourceServer);\n        using var destinationFileText = ToLmbcs(destinationFile);\n        using var destinationServerText = ToLmbcs(destinationServer);\n        nint sourceNetworkPath = 0;\n        nint destinationNetworkPath = 0;\n        try\n        {\n            var sourcePath = sourceFileText.Pointer;\n            if (sourceServer.Length > 0)\n            {\n                sourceNetworkPath = System.Runtime.InteropServices.Marshal.AllocHGlobal(4096);\n                Zero(sourceNetworkPath, 4096);\n                Check(Resolve<OSPathNetConstructDelegate>(\"OSPathNetConstruct\")(0, sourceServerText.Pointer, sourceFileText.Pointer, sourceNetworkPath), \"OSPathNetConstruct\");\n                sourcePath = sourceNetworkPath;\n            }\n\n            var destinationPath = destinationFileText.Pointer;\n            if (destinationServer.Length > 0)\n            {\n                destinationNetworkPath = System.Runtime.InteropServices.Marshal.AllocHGlobal(4096);\n                Zero(destinationNetworkPath, 4096);\n                Check(Resolve<OSPathNetConstructDelegate>(\"OSPathNetConstruct\")(0, destinationServerText.Pointer, destinationFileText.Pointer, destinationNetworkPath), \"OSPathNetConstruct\");\n                destinationPath = destinationNetworkPath;\n            }\n\n            var noteClass = includeDocuments ? (ushort)0x7FFF : (ushort)0x7FFE;\n            Check(Resolve<NSFDbCreateAndCopyDelegate>(\"NSFDbCreateAndCopy\")(sourcePath, destinationPath, noteClass, 0, 0, out var db), \"NSFDbCreateAndCopy\");\n            return db;\n        }\n        finally\n        {\n            if (destinationNetworkPath != 0) System.Runtime.InteropServices.Marshal.FreeHGlobal(destinationNetworkPath);\n            if (sourceNetworkPath != 0) System.Runtime.InteropServices.Marshal.FreeHGlobal(sourceNetworkPath);\n        }\n    }\n\n    internal void DeleteDatabase(string server, string file)\n    {\n        EnsureInitialized();\n        using var fileText = ToLmbcs(file);\n        using var serverText = ToLmbcs(server);\n        nint networkPath = 0;\n        try\n        {\n            var path = fileText.Pointer;\n            if (server.Length > 0)\n            {\n                networkPath = System.Runtime.InteropServices.Marshal.AllocHGlobal(4096);\n                Zero(networkPath, 4096);\n                Check(Resolve<OSPathNetConstructDelegate>(\"OSPathNetConstruct\")(0, serverText.Pointer, fileText.Pointer, networkPath), \"OSPathNetConstruct\");\n                path = networkPath;\n            }\n            Check(Resolve<NSFDbDeleteDelegate>(\"NSFDbDelete\")(path), \"NSFDbDelete\");\n        }\n        finally { if (networkPath != 0) System.Runtime.InteropServices.Marshal.FreeHGlobal(networkPath); }\n    }\n\n    internal XPScriptNotesTimeDate GetDatabaseCreated(nint db)",
            "native-database-create-copy-remove");

        source = ReplaceRequired(
            source,
            "    internal delegate ushort NSFDbIDGetDelegate(nint db, out XPScriptNotesTimeDate databaseId);",
            "    internal delegate ushort NSFDbCreateDelegate(nint pathName, ushort dbClass, int forceCreation);\n    [System.Runtime.InteropServices.UnmanagedFunctionPointer(System.Runtime.InteropServices.CallingConvention.Winapi)]\n    internal delegate ushort NSFDbCreateAndCopyDelegate(nint sourcePath, nint destinationPath, ushort noteClass, ushort limit, uint flags, out nint db);\n    [System.Runtime.InteropServices.UnmanagedFunctionPointer(System.Runtime.InteropServices.CallingConvention.Winapi)]\n    internal delegate ushort NSFDbDeleteDelegate(nint pathName);\n    [System.Runtime.InteropServices.UnmanagedFunctionPointer(System.Runtime.InteropServices.CallingConvention.Winapi)]\n    internal delegate ushort NSFDbIDGetDelegate(nint db, out XPScriptNotesTimeDate databaseId);",
            "native-database-create-copy-remove-delegates");

        return source;
    }

    public static string ApplyBuiltSurface(string source)
    {
        ArgumentNullException.ThrowIfNull(source);
        source = ReplaceRequired(source, "internal nint CreateDatabaseCopy(", "internal uint CreateDatabaseCopy(", "built-create-copy-return");
        source = ReplaceRequired(source, "out nint db);", "out uint db);", "built-create-copy-delegate");
        return source;
    }

    private static string ReplaceRequired(string source, string oldValue, string newValue, string stage)
    {
        if (!source.Contains(oldValue, StringComparison.Ordinal))
            throw new CompilerException("Unable to apply NotesDatabase lifecycle surface (" + stage + ").");
        return source.Replace(oldValue, newValue, StringComparison.Ordinal);
    }
}
